"""V3 uint8 memmap cache shard builder (Kaggle CPU, internet off). Generated by build.py.

Output (/kaggle/working): slices.npy [total,256,256] uint8 (np.lib.format), index.csv (one row
per train_series.csv series of this shard's studies), summary.json, checksums.sha256.
Studies are assigned by sha256(StudyInstanceUID) % NSHARD. Nothing is excluded from caching;
partition/exclude columns come from the frozen dev split (excluded = 58 expert + 7 linked).
"""
import csv
import collections
import hashlib
import json
import os
import sys
import time
from concurrent.futures import ProcessPoolExecutor, as_completed
from pathlib import Path

import numpy as np

SHARD, NSHARD, PILOT = __SHARD__, __NSHARD__, __PILOT__
SOURCES = __SOURCES__
SRC = Path("/tmp/v3src")
SRC.mkdir(parents=True, exist_ok=True)
for name, text in SOURCES.items():
    (SRC / name).write_text(text, encoding="utf-8")
sys.path.insert(0, str(SRC))
from canon import OUT_PX, canon_series  # noqa: E402

COMP = next(p for p in (Path("/kaggle/input/competitions/rsna-knee-abnormality-detection"),
                        Path("/kaggle/input/rsna-knee-abnormality-detection")) if p.is_dir())
SPLIT = next(p for p in (Path("/kaggle/input/rsna-knee-v2-frozen-dev-split/split.csv"),
                         Path("/kaggle/input/datasets/aymenslimani/rsna-knee-v2-frozen-dev-split/split.csv"))
             if p.is_file())
OUT = Path("/kaggle/working")
NPY = OUT / "slices.npy"
MAX_BYTES = 18.5 * 2**30


def h(uid):
    return int(hashlib.sha256(uid.encode()).hexdigest()[:8], 16)


def paths_of(row):
    return sorted((COMP / "train_series" / row["StudyInstanceUID"] / row["SeriesInstanceUID"]).glob("*.dcm"))


def init():
    import torch
    torch.set_num_threads(1)


def work(i, row, start, count):
    t0 = time.time()
    try:
        x, m = canon_series(paths_of(row))
        if len(x) != count:
            raise ValueError(f"slice count {len(x)} != files {count}")
        mm = np.load(NPY, mmap_mode="r+")
        mm[start:start + count] = x
        mm.flush()
        del mm
        return i, m, "", time.time() - t0
    except Exception as e:  # counted per type, never substituted
        return i, None, f"{type(e).__name__}: {e}"[:200], time.time() - t0


def sha256_file(p):
    d = hashlib.sha256()
    with open(p, "rb") as f:
        for b in iter(lambda: f.read(1 << 24), b""):
            d.update(b)
    return d.hexdigest()


def parity(rows, starts, counts, index):
    """Re-decode every ok series directly and compare with the stored cache (exact), plus an
    independent cv2 INTER_AREA path on the middle slice of each series (correlation)."""
    import cv2
    mm = np.load(NPY, mmap_mode="r")
    exact, mismatch, corrs, mads = 0, 0, [], []
    for i, row in enumerate(rows):
        if index[i]["ok"] != "1":
            continue
        cached = mm[starts[i]:starts[i] + counts[i]]
        x, m = canon_series(paths_of(row))
        same = np.array_equal(x, cached) and np.allclose(
            m["positions"], [float(v) for v in index[i]["positions"].split(";")], atol=1e-3)
        exact += same
        mismatch += not same
        # independent path: raw DICOM -> geometry from stored flags -> crop -> cv2 area -> lo/hi
        import pydicom
        dss = [pydicom.dcmread(str(p)) for p in paths_of(row)]
        nvec = np.cross(*np.asarray(dss[0].ImageOrientationPatient, float).reshape(2, 3))
        ax = int(np.argmax(np.abs(nvec)))
        key = [float(np.asarray(d.ImagePositionPatient, float) @ nvec) * np.sign(nvec[ax]) for d in dss]
        d = dss[int(np.argsort(key)[len(dss) // 2])]
        a = d.pixel_array.astype(np.float32) * float(getattr(d, "RescaleSlope", 1)) + float(getattr(d, "RescaleIntercept", 0))
        if index[i]["transpose"] == "1":
            a = a.T
        a = a[::-1 if index[i]["flip_rows"] == "1" else 1, ::-1 if index[i]["flip_cols"] == "1" else 1]
        ch, cw = round(160 / float(index[i]["row_spacing"])), round(160 / float(index[i]["col_spacing"]))
        H, W = a.shape
        big = np.full((max(H, ch), max(W, cw)), a.min(), np.float32)
        big[(big.shape[0] - H) // 2:(big.shape[0] - H) // 2 + H, (big.shape[1] - W) // 2:(big.shape[1] - W) // 2 + W] = a
        r0, c0 = (big.shape[0] - ch) // 2, (big.shape[1] - cw) // 2
        crop = np.ascontiguousarray(big[r0:r0 + ch, c0:c0 + cw])
        res = cv2.resize(crop, (OUT_PX, OUT_PX), interpolation=cv2.INTER_AREA if min(ch, cw) >= OUT_PX else cv2.INTER_LINEAR)
        lo, hi = float(index[i]["lo"]), float(index[i]["hi"])
        ref = np.clip((res - lo) / (hi - lo), 0, 1) * 255
        got = cached[len(dss) // 2].astype(np.float32)
        corrs.append(float(np.corrcoef(ref.ravel(), got.ravel())[0, 1]))
        mads.append(float(np.abs(ref - got).mean()))
    return {"series_checked": exact + mismatch, "exact_match": int(exact), "mismatch": int(mismatch),
            "indep_corr_min": min(corrs) if corrs else None, "indep_corr_median": float(np.median(corrs)) if corrs else None,
            "indep_mad_uint8_median": float(np.median(mads)) if mads else None, "indep_mad_uint8_max": max(mads) if mads else None}


def main():
    t_start = time.time()
    with open(COMP / "train_series.csv", newline="", encoding="utf-8") as f:
        all_rows = list(csv.DictReader(f))
    with open(SPLIT, newline="", encoding="utf-8") as f:
        part = {r["StudyInstanceUID"]: r["partition"] for r in csv.DictReader(f)}
    studies = sorted({r["StudyInstanceUID"] for r in all_rows})
    mine = set(sorted(studies, key=h)[:20]) if PILOT else {s for s in studies if h(s) % NSHARD == SHARD}
    rows = sorted((r for r in all_rows if r["StudyInstanceUID"] in mine),
                  key=lambda r: (r["StudyInstanceUID"], r["SeriesInstanceUID"]))
    counts = [len(paths_of(r)) for r in rows]
    starts = np.concatenate([[0], np.cumsum(counts)[:-1]]).astype(int).tolist()
    total = int(sum(counts))
    nbytes = total * OUT_PX * OUT_PX
    print(f"shard {SHARD}/{NSHARD} pilot={PILOT}: {len(mine)} studies, {len(rows)} series, {total} slices, {nbytes / 2**30:.2f} GiB", flush=True)
    if nbytes > MAX_BYTES:
        raise SystemExit(f"shard too large: {nbytes / 2**30:.2f} GiB")
    mm = np.lib.format.open_memmap(NPY, mode="w+", dtype=np.uint8, shape=(total, OUT_PX, OUT_PX))
    del mm

    index = [None] * len(rows)
    errors = collections.Counter()
    t0 = time.time()
    with ProcessPoolExecutor(os.cpu_count(), initializer=init) as ex:
        order = sorted(range(len(rows)), key=lambda i: -counts[i])  # big series first
        futs = [ex.submit(work, i, rows[i], starts[i], counts[i]) for i in order]
        for k, fut in enumerate(as_completed(futs)):
            i, m, err, sec = fut.result()
            r = rows[i]
            pt = part.get(r["StudyInstanceUID"], "missing")
            rec = {"study": r["StudyInstanceUID"], "series": r["SeriesInstanceUID"], "plane": r["Anatomical_Plane"],
                   "fluid": r["Fluid_Sensitive"], "fatsat": r["Fat_Suppression"], "partition": pt,
                   "exclude": int(pt not in ("candidate_train", "candidate_validation")),
                   "start": starts[i], "length": counts[i] if m else 0, "files": counts[i], "ok": int(m is not None),
                   "error": err, "seconds": round(sec, 2)}
            if m:
                rec.update({"plane_geom": m["plane_geom"], "positions": ";".join(f"{p:.3f}" for p in m["positions"]),
                            "row_spacing": m["row_spacing"], "col_spacing": m["col_spacing"], "thickness": m["thickness"],
                            "laterality": m["laterality"], "laterality_source": m["laterality_source"],
                            "centre_x_mm": m["centre_x_mm"], "lo": m["lo"], "hi": m["hi"],
                            "transpose": int(m["transpose"]), "flip_rows": int(m["flip_rows"]), "flip_cols": int(m["flip_cols"]),
                            "bad_slices": m["bad_slices"], "orig_rows": m["orig_shape"][0], "orig_cols": m["orig_shape"][1]})
            else:
                errors[err.split(":")[0]] += 1
            index[i] = rec
            if k % 200 == 0:
                print(f"{k}/{len(rows)} series, {time.time() - t0:.0f}s, errors {dict(errors)}", flush=True)
    build_s = time.time() - t0

    cols = ["study", "series", "plane", "fluid", "fatsat", "partition", "exclude", "start", "length", "files", "ok", "error",
            "plane_geom", "positions", "row_spacing", "col_spacing", "thickness", "laterality", "laterality_source",
            "centre_x_mm", "lo", "hi", "transpose", "flip_rows", "flip_cols", "bad_slices", "orig_rows", "orig_cols", "seconds"]
    with open(OUT / "index.csv", "w", newline="", encoding="utf-8") as f:
        w = csv.DictWriter(f, cols, restval="")
        w.writeheader()
        w.writerows(index)
    sums = {n: sha256_file(OUT / n) for n in ("slices.npy", "index.csv")}
    (OUT / "checksums.sha256").write_text("".join(f"{v}  {k}\n" for k, v in sums.items()))
    ok = [r for r in index if r["ok"]]
    summary = {
        "shard": SHARD, "nshard": NSHARD, "pilot": PILOT, "cpu_count": os.cpu_count(),
        "studies": len(mine), "series": len(rows), "series_ok": len(ok), "series_failed": len(rows) - len(ok),
        "failures_by_type": dict(errors), "slices_total": total, "slices_bytes": nbytes, "sha256": sums,
        "excluded_studies": len({r["study"] for r in index if r["exclude"]}),
        "laterality": dict(collections.Counter(f"{r['laterality']}|{r['laterality_source']}" for r in ok)),
        "build_seconds": round(build_s, 1), "seconds_per_study": round(build_s / max(1, len(mine)), 3),
    }
    if PILOT:
        tp = time.time()
        str_index = [{k: str(v) for k, v in r.items()} for r in index]
        summary["parity"] = parity(rows, starts, counts, str_index)
        summary["parity_seconds"] = round(time.time() - tp, 1)
        summary["projected_full_bytes"] = nbytes / max(1, len(mine)) * len(studies)
        summary["projected_full_cpu_hours_4core"] = build_s / max(1, len(mine)) * len(studies) / 3600
    summary["total_seconds"] = round(time.time() - t_start, 1)
    (OUT / "summary.json").write_text(json.dumps(summary, indent=1))
    print(json.dumps(summary, indent=1))


if __name__ == "__main__":
    main()
